text:
    color: var(--color-text-secondary);
    margin-block-end: var(--qr-gap);
  }

  img {
    max-inline-size: 420px;
    image-rendering: pixelated;
  }
}

#qrExportSummaryList {
  padding: 0;
  margin: 0;
  list-style-position: inside;
  line-height: 2rem;

  & > li > ul {
    list-style-type: disc;
    display: grid;

    & li {
      overflow: hidden;
      text-overflow: ellipsis;
    }
  }
}

#qrExportSummary h2 {
  font-size: 1em;
  font-weight: normal;
  margin: 0;
}

#qrExportRestart {
  margin-block-start: 24px;
}

